package com.amtsolution.patterns.strategy;
import java.math.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class ContextoEncargo { private final Map<String,CalculoEncargoStrategy> estrategias; public ContextoEncargo(List<CalculoEncargoStrategy> itens){estrategias=new HashMap<>();itens.forEach(e->estrategias.put(e.nome(),e));} public ResultadoCalculo simular(String nome,BigDecimal valor,BigDecimal percentual,int dias){CalculoEncargoStrategy e=estrategias.get(nome);if(e==null)throw new IllegalArgumentException("Estratégia de encargo inválida.");BigDecimal ajuste=e.calcular(valor,percentual==null?BigDecimal.ZERO:percentual,dias);return new ResultadoCalculo(nome,valor,valor.add(ajuste),ajuste);} }
